using System;
using FiresCore.Logging;
using UnityEngine;

namespace FiresWayshrines
{
    // FiresWayshrines' console banners, rendered through the shared Banner engine.
    //
    //   PrintBig()  → trilithon portal arch with a glowing gate and the FIRES
    //                 WAYSHRINES brand. Fires at the very top of Setup as the
    //                 load announcement.
    //   Print()     → compact stone arch over a status frame ("PATHS OPEN").
    //                 Fires once at first WorldStart.
    //
    // Art generated by Tools\gen_fires_banner.ps1 (spec: FiresWayshrines).
    // Color zones: sky (White/Cyan), stone pillars (Gray/DarkGray), portal
    // glow (Cyan/DarkCyan), brand (White/Cyan), ground (DarkGray).
    internal static class FiresWayshrinesBanner
    {
        private static bool s_compactPrinted;

        public static void PrintBig()
        {
            try
            {
                EmitHeader("Fires Wayshrines Loading...");
                Banner.Print(ToSegments(s_bigLines));
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresWayshrines] Big banner failed: {ex.Message}");
            }
        }

        public static void Print()
        {
            if (s_compactPrinted) return;
            s_compactPrinted = true;
            try
            {
                EmitHeader("Fires Wayshrines Loaded.");
                Banner.Print(s_compactLines);
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresWayshrines] Compact banner failed: {ex.Message}");
            }
        }

        // Routes the one-line header through the plugin's BepInEx log source (not
        // Debug.Log) so it prints once, colored by FiresLogColorPatch via the
        // Fires source name, without a raw white stdout duplicate.
        private static void EmitHeader(string text)
        {
            if (FiresWayshrinesPlugin.Log != null) FiresWayshrinesPlugin.Log.LogInfo(text);
            else Debug.Log($"[FiresWayshrines] {text}");
        }

        private static Banner.Segment[][] ToSegments((string text, ConsoleColor color)[] lines)
        {
            var result = new Banner.Segment[lines.Length][];
            for (int i = 0; i < lines.Length; i++)
                result[i] = new[] { new Banner.Segment(lines[i].text, lines[i].color) };
            return result;
        }

        // Compact banner — stone arch with a swirling gate over a status frame.
        // 31-char frame body (3 lead + ╔ + 26 ═ + ╗); 🌀 is a surrogate pair, but the console
        // ADVANCES ONE column for it (no VS16), however wide the font paints the glyph, so this row pads it as one cell.
