        {
            new[] { new Banner.Segment("            ▄█████████▄",      ConsoleColor.DarkGray) },
            new[]
            {
                new Banner.Segment("            ██ ",  ConsoleColor.Gray),
                new Banner.Segment("░▒▓▒░",           ConsoleColor.Cyan),
                new Banner.Segment(" ██",              ConsoleColor.Gray),
            },
            new[]
            {
                new Banner.Segment("            ██ ",  ConsoleColor.Gray),
                new Banner.Segment("▒▓█▓▒",           ConsoleColor.DarkCyan),
                new Banner.Segment(" ██",              ConsoleColor.Gray),
            },
            new[]
            {
                new Banner.Segment("            ██ ",  ConsoleColor.Gray),
                new Banner.Segment("░▒▓▒░",           ConsoleColor.Cyan),
                new Banner.Segment(" ██",              ConsoleColor.Gray),
            },
            new[] { new Banner.Segment("           ▄██▄     ▄██▄",    ConsoleColor.DarkGray) },
            new[] { new Banner.Segment("   ╔══════════════════════════╗", ConsoleColor.DarkGray) },
            new[]
            {
                new Banner.Segment("   ║   ",              ConsoleColor.DarkGray),
                new Banner.Segment("[",                    ConsoleColor.Gray),
                new Banner.Segment("██████████████████",   ConsoleColor.Green),
                new Banner.Segment("]",                    ConsoleColor.Gray),
                new Banner.Segment("   ║",                 ConsoleColor.DarkGray),
            },
            new[]
            {
                new Banner.Segment("   ║      ",           ConsoleColor.DarkGray),
                new Banner.Segment("🌀 PATHS OPEN",        ConsoleColor.Cyan),
                new Banner.Segment("        ║",             ConsoleColor.DarkGray),
            },
            new[] { new Banner.Segment("   ╚══════════════════════════╝", ConsoleColor.DarkGray) },
            new[] { new Banner.Segment("    FIRES WAYSHRINES",         ConsoleColor.Cyan) },
            new Banner.Segment[0],
            new[] { new Banner.Segment("   Fires Wayshrines Loaded",   ConsoleColor.Magenta) },
        };

